        }

        @Override
        public int getParcelas(Integer parcelasRequisitadas) {
            return 1;
        }
    },
    CARTAO {
        @Override
        public void validarParcelas(Integer parcelas) {
            int p = parcelas == null ? 1 : parcelas;
            if (p < 1 || p > 12) {
