    @Test
    void formaPagamentoIndisponivel_boletoAcima1000() {
        ResumoRequest request = new ResumoRequest(
            List.of(new ItemPedido("Produto Caro", new BigDecimal("1200.00"), 1, new BigDecimal("1.0"))),
            "ECONOMICA",
