37	        BigDecimal seguro = regiao.calcularSeguro(subtotalProdutos);
38	
39	        BigDecimal totalPedido = subtotalProdutos
40	            .subtract(descontoCupom)
41	            .add(frete)
42	            .add(seguro)
43	            .setScale(2, java.math.RoundingMode.HALF_EVEN);
44	
45	        FormaPagamento formaPagamento = FormaPagamento.fromString(request.formaPagamento());
46	        formaPagamento.validarParcelas(request.parcelas());
47	        formaPagamento.validarDisponibilidade(totalPedido);
48	
49	        int parcelas = formaPagamento.getParcelas(request.parcelas());
50	        BigDecimal totalFinal = formaPagamento.calcularTotalFinal(totalPedido, parcelas);
51	        BigDecimal ajustePagamento = formaPagamento.calcularAjuste(totalPedido, parcelas);
52	        BigDecimal valorParcela = formaPagamento.calcularValorParcela(totalFinal, parcelas);
53	
54	        BigDecimal credito = nivelClube.calcularCredito(subtotalProdutos);
55	        boolean brinde = nivelClube.ganhaBrinde(subtotalProdutos);
56	
57	        return new ResumoResponse(
58	            subtotalProdutos,
59	            descontoCupom,
60	            frete,
61	            modalidade.getPrazoEntregaDias(),
62	            seguro,
63	            ajustePagamento,
64	            totalFinal,
65	            parcelas,
66	            valorParcela,
67	            credito,
68	            brinde
69	        );
70	    }
71	
72	    private void validarPedido(List<ItemPedido> itens) {
73	        if (itens == null || itens.isEmpty()) {
74	            throw new CheckoutException("PEDIDO_INVALIDO");
75	        }
76	
77	        for (ItemPedido item : itens) {
78	            if (item.precoUnitario() == null || item.precoUnitario().compareTo(BigDecimal.ZERO) <= 0 ||
79	                item.quantidade() == null || item.quantidade() <= 0 ||
80	                item.pesoKg() == null || item.pesoKg().compareTo(BigDecimal.ZERO) <= 0) {
81	                throw new CheckoutException("PEDIDO_INVALIDO");
82	            }
83	        }
84	    }
85	
86	    private BigDecimal calcularSubtotalProdutos(List<ItemPedido> itens) {
87	        BigDecimal subtotal = BigDecimal.ZERO;
88	        for (ItemPedido item : itens) {
89	            BigDecimal valorItem = item.precoUnitario()
90	                .multiply(BigDecimal.valueOf(item.quantidade()))
91	                .setScale(2, java.math.RoundingMode.HALF_EVEN);
92	            subtotal = subtotal.add(valorItem);
93	        }
94	        return subtotal.setScale(2, java.math.RoundingMode.HALF_EVEN);
95	    }
96	
97	    private BigDecimal calcularPesoTotal(List<ItemPedido> itens) {
98	        BigDecimal pesoTotal = BigDecimal.ZERO;
99	        for (ItemPedido item : itens) {
100	            BigDecimal pesoItem = item.pesoKg().multiply(BigDecimal.valueOf(item.quantidade()));
101	            pesoTotal = pesoTotal.add(pesoItem);
102	        }
103	        return pesoTotal;
104	    }
105	}
